const translations = [
  // 0: fb45f5b3-f5bd-4e0b-9636-91175b2595d4 (Hadith des Ifk)
  "Abu ar-Rabi‘ Sulayman ibn Dawud berichtete uns, und Ahmad erklärte mir einen Teil davon: Fulayh ibn Sulayman berichtete uns von Ibn Schihab az-Zuhri, von ‘Urwah ibn az-Zubayr, Sa‘id ibn al-Musayyab, ‘Alqamah ibn Waqqas al-Laythi und ‘Ubaydullah ibn ‘Abdullah ibn ‘Utbah, von ‘A’ischah (möge Allah mit ihr zufrieden sein), der Gattin des Propheten (Friede sei auf ihm), bezüglich dessen, was die Urheber der Verleumdung (Ahl al-Ifk) über sie gesagt hatten, und wie Allah ihre Unschuld daran erwies. Az-Zuhri sagte: Jeder von ihnen berichtete mir einen Teil ihres Berichts; manche von ihnen hatten mehr davon behalten als andere und trugen die Erzählung sicherer vor. Und ich habe von jedem von ihnen den Bericht behalten, den er mir von ‘A’ischah überlieferte, wobei einige Teile ihrer Berichte einander bestätigen. Sie gaben an, dass ‘A’ischah sagte: Wenn der Gesandte Allahs (Friede sei auf ihm) eine Reise antreten wollte, pflegte er das Los unter seinen Frauen zu werfen; und wessen Los herauskam, mit der zog er aus. So warf er bei einem Feldzug, den er unternahm, das Los unter uns, und mein Los kam heraus. So zog ich mit ihm aus, nachdem der Vers über den Hidschab herabgesandt worden war. Ich wurde in einer Sänfte getragen und stieg in ihr ab. Wir zogen dahin, bis der Gesandte Allahs (Friede sei auf ihm) jenen Feldzug beendet hatte und auf dem Rückweg war. Als wir uns Medina näherten, kündigte er eines Nachts den Aufbruch an. Da stand ich auf, als sie den Aufbruch ankündigten, und ging hinaus, bis ich das Heerlager hinter mir gelassen hatte. Als ich meine Notdurft verrichtet hatte, kehrte ich zu meiner Sänfte zurück und tastete an meine Brust; da bemerkte ich, dass meine Halskette aus Onyx-Perlen von Zafar gerissen war. So ging ich zurück und suchte nach meiner Halskette, und das Suchen hielt mich auf. Inzwischen kamen jene Männer heran, die meine Sänfte aufzuladen pflegten; sie hoben meine Sänfte hoch und banden sie auf dem Kamel fest, auf dem ich ritt, in der Annahme, ich säße darin. Zu jener Zeit waren die Frauen leicht an Gewicht und nicht schwer oder von Fleisch überdeckt; sie aßen nur wenig Speise. Daher empfanden die Leute beim Hochheben der Sänfte keine Ungereimtheit bezüglich des Gewichts, und ich war ein junges Mädchen. So trieben sie das Kamel an und zogen weiter. Ich fand meine Halskette erst, nachdem das Heer weitergezogen war. Als ich an ihren Lagerplatz kam, war dort niemand mehr, weder ein Rufer noch ein Antwortender. Da begab ich mich zu meinem Rastplatz, an dem ich gewesen war, in der Erwartung, sie würden mein Fehlen bemerken und zu mir zurückkehren. Während ich an meinem Platz saß, übermannte mich der Schlaf und ich schlief ein. Safwan ibn al-Mu‘attal as-Sulami, danach adh-Dhakwani, war hinter dem Heer zurückgeblieben. Am Morgen erreichte er den Ort, an dem ich lag, und sah die dunkle Gestalt eines schlafenden Menschen. Da trat er heran und erkannte mich, als er mich sah; er hatte mich noch vor dem Gebot des Hidschabs gesehen. Da erwachte ich durch sein Ausrufen: ‚Wahrlich, wir gehören Allah, und zu Ihm kehren wir zurück!‘, als er sein Kamel niederknien ließ. Da trat er auf dessen Vorderbein, und ich stieg auf. Er führte das Kamel mit mir am Zügel, bis wir das Heer erreichten, nachdem sie in der brennenden Mittagshitze Rast eingelegt hatten. Da gingen manche Leute zugrunde, und derjenige, der den Hauptteil der Verleumdung führte, war ‘Abdullah ibn Ubayy ibn Salul. Wir trafen in Medina ein, und ich erkrankte dort einen ganzen Monat lang, während die Leute die Worte der Verleumder verbreiteten. Was mich während meiner Krankheit jedoch tief beunruhigte, war, dass ich vom Propheten (Friede sei auf ihm) nicht jene vertraute Fürsorge spürte, die ich sonst von ihm sah, wenn ich krank war; er trat nur herein, grüßte und sagte: ‚Wie geht es jener da?‘ Ich wusste von alledem nichts, bis ich genesen war. Da ging ich eines Nachts mit Umm Mistah nach al-Manasi‘ hinaus, dem Ort, an dem wir unsere Notdurft verrichteten; und wir pflegten nur von Nacht zu Nacht hinauszugehen, bevor wir Aborte nahe an unseren Häusern errichteten. Unser Brauch war der der alten Araber im offenen Land beim Verrichten der Notdurft. Da gingen ich und Umm Mistah bint Abi Ruhm umher. Als sie über ihr Übergewand stolperte, rief sie aus: ‚Zugrunde gehen soll Mistah!‘ Da sagte ich zu ihr: ‚Welch übles Wort sprichst du da! Beschimpfst du etwa einen Mann, der an Badr teilgenommen hat?‘ Da erwiderte sie: ‚O du Ärmste, hast du denn nicht gehört, was sie sagen?‘ Und sie berichtete mir die Worte der Verleumder. Da verschlimmerte sich meine Krankheit nur noch mehr. Als ich nach Hause zurückkehrte, trat der Gesandte Allahs (Friede sei auf ihm) herein, grüßte und sagte: ‚Wie geht es jener da?‘ Da sagte ich: ‚Erlaubst du mir, zu meinen Eltern zu gehen?‘ – denn ich wollte mir bei ihnen Gewissheit über diese Nachricht verschaffen. Der Gesandte Allahs (Friede sei auf ihm) erlaubte es mir, und ich ging zu meinen Eltern. Da sagte ich zu meiner Mutter: ‚O meine Mutter, worüber reden die Menschen?‘ Sie sprach: ‚O mein Töchterchen, nimm es nicht so schwer! Bei Allah, selten gibt es eine schöne Frau, die von einem Mann geliebt wird und Nebenfrauen hat, ohne dass diese viel gegen sie vorbringen.‘ Da rief ich aus: ‚Gepriesen sei Allah! Haben die Menschen wirklich darüber geredet?‘ Ich weinte jene ganze Nacht bis zum Morgen; weder versiegten meine Tränen, noch fand ich Schlaf. Am Morgen, als die Offenbarung ausblieb, rief der Gesandte Allahs (Friede sei auf ihm) ‘Ali ibn Abi Talib und Usamah ibn Zayd zu sich, um sie über die Trennung von seiner Frau zu befragen. Was Usamah betrifft, so riet er ihm gemäß dem, was er an Unschuld für die Angehörigen des Gesandten Allahs und an Zuneigung für sie wusste; er sagte: ‚O Gesandter Allahs, sie sind deine Angehörigen, und bei Allah, wir wissen über sie nichts als Gutes!‘ Was aber ‘Ali ibn Abi Talib betrifft, so sagte er: ‚O Gesandter Allahs, Allah hat dir keine Enge auferlegt, und es gibt viele Frauen außer ihr! Frage doch die Magd, sie wird dir die Wahrheit sagen.‘ Da rief der Gesandte Allahs (Friede sei auf ihm) Barirah herbei und fragte: ‚O Barirah, hast du je an ihr etwas gesehen, was dir Zweifel einflößte?‘ Da sprach Barirah: ‚Nein, bei Dem, Der dich mit der Wahrheit gesandt hat! Niemals habe ich an ihr etwas gesehen, was man ihr vorwerfen könnte, außer dass sie ein junges Mädchen ist, das über dem Teig ihrer Familie einschläft, sodass das Haustier herbeikommt und davon frisst.‘ Da stand der Gesandte Allahs (Friede sei auf ihm) noch an jenem Tag auf und bat um Genugtuung gegen ‘Abdullah ibn Ubayy ibn Salul. Der Gesandte Allahs (Friede sei auf ihm) sprach auf der Kanzel: ‚Wer hilft mir gegen einen Mann, dessen Kränkung meine Familie erreicht hat? Bei Allah, ich weiß über meine Familie nichts als Gutes! Und sie haben einen Mann erwähnt, über den ich ebenfalls nichts als Gutes weiß; er betrat mein Haus niemals anders als in meiner Begleitung!‘ Da stand Sa‘d ibn Mu‘adh auf und sagte: ‚O Gesandter Allahs, bei Allah, ich werde dir gegen ihn Genugtuung verschaffen! Wenn er aus dem Stamm Aws ist, schlagen wir ihm den Kopf ab; und wenn er von unseren Brüdern aus dem Stamm Khazraj ist, so befiehl uns, und wir führen deinen Befehl gegen ihn aus.‘ Da stand Sa‘d ibn ‘Ubadah auf – und er war das Oberhaupt der Khazraj; zuvor war er ein rechtschaffener Mann gewesen, doch der Stammesstolz übermannte ihn –; er sprach: ‚Bei Allahs Leben, du lügst! Du wirst ihn nicht töten, und du vermagst es auch gar nicht!‘ Da sprang Usayd ibn Hudayr auf und sagte: ‚Bei Allahs Leben, du lügst! Bei Allah, wir werden ihn gewiss töten! Denn du bist ein Heuchler, der für die Heuchler streitet!‘ Da gerieten die beiden Stämme, Aws und Khazraj, derart in Erregung, dass sie aufeinander losgehen wollten, während der Gesandte Allahs (Friede sei auf ihm) auf der Kanzel stand. Er stieg herab und beruhigte sie, bis sie schwiegen, und er schwieg ebenfalls. Ich weinte jenen ganzen Tag; meine Tränen versiegten nicht, und kein Schlaf kam über mich. Am nächsten Morgen saßen meine Eltern bei mir; ich hatte zwei Nächte und einen Tag geweint, bis ich glaubte, das Weinen würde mir die Leber zerreißen. Während sie so bei mir saßen und ich weinte, bat eine Frau von den Ansar um Erlaubnis, einzutreten. Ich ließ sie herein, und sie setzte sich nieder und weinte mit mir. Während wir in diesem Zustand waren, trat plötzlich der Gesandte Allahs (Friede sei auf ihm) herein, grüßte und setzte sich nieder; und er hatte sich nicht mehr zu mir gesetzt, seit jenes geredet worden war, was man geredet hatte. Ein ganzer Monat war vergangen, ohne dass ihm bezüglich meiner Angelegenheit eine Offenbarung zuteilgeworden war. Er sprach das Glaubensbekenntnis und sagte dann: ‚O ‘A’ischah, mir ist über dich dies und jenes zu Ohren gekommen. Wenn du unschuldig bist, wird Allah deine Unschuld gewiss erweisen; und wenn du eine Sünde begangen hast, so bitte Allah um Vergebung und kehre reuevoll zu Ihm um! Denn wenn der Diener seine Sünde eingesteht und dann bereut, nimmt Allah seine Reue an.‘ Als der Gesandte Allahs (Friede sei auf ihm) seine Rede beendet hatte, versiegten meine Tränen gänzlich, sodass ich keinen einzigen Tropfen mehr spürte. Da sprach ich zu meinem Vater: ‚Antworte dem Gesandten Allahs (Friede sei auf ihm) für mich!‘ Er sagte: ‚Bei Allah, ich weiß nicht, was ich dem Gesandten Allahs (Friede sei auf ihm) sagen soll!‘ Da sprach ich zu meiner Mutter: ‚Antworte du dem Gesandten Allahs (Friede sei auf ihm) für mich auf das, was er sagte!‘ Sie sagte: ‚Bei Allah, ich weiß nicht, was ich dem Gesandten Allahs (Friede sei auf ihm) sagen soll!‘ Da sprach ich – und ich war ein junges Mädchen, das noch nicht viel aus dem Koran rezitieren konnte –: ‚Bei Allah, ich weiß wohl, dass ihr diese Rede der Leute gehört habt, sodass sie sich in euren Herzen festgesetzt hat und ihr ihr Glauben schenktet. Wenn ich euch nun sage: Ich bin unschuldig – und Allah weiß, dass ich unschuldig bin –, so würdet ihr mir nicht glauben; und wenn ich vor euch etwas eingestehe – während Allah weiß, dass ich unschuldig bin –, so würdet ihr mir gewiss glauben! Bei Allah, ich finde für mich und euch kein anderes Gleichnis als das des Vaters von Joseph, als er sagte: „So gilt es, schöne Geduld zu üben; und Allah ist derjenige, Dessen Hilfe gegen das anzuflehen ist, was ihr beschreibt“ (Sure 12, Vers 18 bis 18).‘ Dann wandte ich mich ab und legte mich auf mein Bett, in der Hoffnung, dass Allah meine Unschuld erweisen würde. Doch bei Allah, ich hätte niemals gedacht, dass Allah meinetwegen eine Offenbarung herabsenden würde, die rezitiert wird! Denn mein Stellenwert bei mir selbst war viel zu gering, als dass der Koran über mich sprechen würde. Ich hoffte lediglich, dass der Gesandte Allahs (Friede sei auf ihm) einen Traum sehen würde, in dem Allah meine Unschuld erwies. Doch bei Allah, der Gesandte Allahs hatte seinen Platz noch nicht verlassen und niemand aus den Hausgenossen war hinausgegangen, da ereilte ihn die Offenbarung. Da überkam ihn jener Zustand, der ihn bei der Offenbarung zu überkommen pflegte, sodass ihm an einem kalten Tag der Schweiß wie Perlen von der Stirn rann, wegen der Schwere des Wortes, das auf ihn herabgesandt wurde. Als jener Zustand vom Gesandten Allahs (Friede sei auf ihm) wich, lächelte er. Das erste Wort, das er sprach, war: ‚O ‘A’ischah, preise Allah; denn Allah hat deine Unschuld erwiesen!‘ Da sagte meine Mutter zu mir: ‚Steh auf und geh zu ihm!‘ Ich sagte: ‚Nein, bei Allah, ich stehe nicht auf, um zu ihm zu gehen, und ich lobe niemanden außer Allah!‘ Da sandte Allah der Erhabene herab: „Gewiss, diejenigen, die die Verleumdung vorgebracht haben, sind eine Schar unter euch...“ (Sure 24, Vers 11 bis 11) und die Verse danach. Als Allah dies zur Erweisung meiner Unschuld herabsandte, sagte Abu Bakr as-Siddiq (möge Allah mit ihm zufrieden sein) – der für Mistah ibn Uthathah wegen dessen Verwandtschaft zu sorgen pflegte –: ‚Bei Allah, niemals werde ich mehr etwas für Mistah ausgeben nach dem, was er über ‘A’ischah gesagt hat!‘ Da sandte Allah der Erhabene herab: „Und es sollen diejenigen unter euch, die Gunst und Wohlstand besitzen, nicht schwören...“ bis zu Seinen Worten: „...Verzeihend, Barmherzig“ (Sure 24, Vers 22 bis 22). Da sprach Abu Bakr: ‚Doch, bei Allah, wahrlich, ich liebe es, dass Allah mir vergibt!‘ Und er nahm die Unterstützung für Mistah wieder auf, wie er es zuvor getan hatte. Und der Gesandte Allahs (Friede sei auf ihm) hatte auch Zaynab bint Jahsch über meine Angelegenheit befragt; er sprach: ‚O Zaynab, was hast du gewusst oder gesehen?‘ Sie antwortete: ‚O Gesandter Allahs, ich bewahre mein Gehör und mein Augenlicht; bei Allah, ich weiß über sie nichts als Gutes!‘ ‘A’ischah sagte: Sie war diejenige unter den Frauen des Propheten, die mit mir um seinen Vorzug wetteiferte, doch Allah bewahrte sie durch ihre Frömmigkeit. Er sagte: Fulayh berichtete uns von Hischam ibn ‘Urwah, von ‘Urwah, von ‘A’ischah und ‘Abdullah ibn az-Zubayr mit einem ähnlichen Bericht. Er sagte: Und Fulayh berichtete uns von Rabi‘ah ibn Abi ‘Abd ar-Rahman und Yahya ibn Sa‘id, von al-Qasim ibn Muhammad ibn Abi Bakr mit einem ähnlichen Bericht.",

  // 1: cda9ab08-cee0-425a-b408-7d1c877c68e9 (Abkommen von al-Hudaybiyyah)
  "‘Abdullah ibn Muhammad berichtete mir: ‘Abd ar-Razzaq berichtete uns: Ma‘mar teilte uns mit; er sagte: Az-Zuhri teilte mir mit; er sagte: ‘Urwah ibn az-Zubayr teilte mir mit, von al-Miswar ibn Makhramah und Marwan, deren Berichte einander bestätigten; er sagte: Der Gesandte Allahs (Friede sei auf ihm) brach zur Zeit von al-Hudaybiyyah auf. Als sie einen Teil des Weges zurückgelegt hatten, sprach der Prophet (Friede sei auf ihm): „Khalid ibn al-Walid befindet sich mit einer Reiterschar der Quraisch als Vorhut bei al-Ghamim, so schlagt den Weg nach rechts ein!“ Bei Allah, Khalid bemerkte sie nicht, bis der Staub des Heeres vor ihm aufstieg; da sprengte er im Galopp davon, um die Quraisch zu warnen. Der Prophet (Friede sei auf ihm) zog weiter, bis er jenen Gebirgspass erreichte, von dem aus man zu ihnen hinabsteigt. Dort kniete seine Kamelstute nieder. Die Leute riefen: „Hü, hü! Steh auf!“, doch sie blieb stur liegen. Da sagten die Leute: „Al-Qaswa’ ist widerspenstig geworden! Al-Qaswa’ ist widerspenstig geworden!“ Da sprach der Prophet (Friede sei auf ihm): „Al-Qaswa’ ist nicht widerspenstig geworden, und das liegt nicht in ihrer Natur; vielmehr hat sie Derselbe zurückgehalten, Der auch den Elefanten zurückhielt.“ Dann sprach er: „Bei Dem, in Dessen Hand meine Seele liegt: Was immer sie von mir an einer Bedingung verlangen, durch die sie die geheiligten Stätten Allahs achten, werde ich ihnen gewähren!“ Dann trieb er sie an, und sie sprang auf. Er wandte sich von ihnen ab und lagerte am äußersten Ende von al-Hudaybiyyah an einem kleinen Wasserloch mit wenig Wasser, aus dem die Leute das Wasser nur schlückchenweise schöpften. Bald hatten die Leute das Wasser völlig aufgebraucht. Da wurde dem Gesandten Allahs (Friede sei auf ihm) geklagt, dass sie durstig seien. Da zog er einen Pfeil aus seinem Köcher und befahl ihnen, ihn in die Quelle zu stecken. Bei Allah, das Wasser sprudelte unaufhörlich für sie hervor, bis sie von dort aufbrachen. Während sie dort verweilten, kam Budayl ibn Warqa’ al-Khuza‘i mit einer Schar seiner Leute vom Stamm Khuza‘ah heran; sie waren loyale Ratgeber des Gesandten Allahs (Friede sei auf ihm) unter den Leuten der Tihamah. Er sagte: „Ich habe Ka‘b ibn Lu’ayy und ‘Amir ibn Lu’ayy an den reichlichen Wasserstellen von al-Hudaybiyyah zurückgelassen; bei ihnen sind die säugenden Kamele mitsamt ihren Jungen. Sie wollen dich bekämpfen und dich vom Hause Allahs fernhalten.“ Da sprach der Gesandte Allahs (Friede sei auf ihm): „Wir sind nicht gekommen, um jemanden zu bekämpfen, sondern wir sind gekommen, um die ‘Umrah zu vollziehen. Wahrlich, der Krieg hat die Quraisch ausgelaugt und ihnen schweren Schaden zugefügt! Wenn sie wollen, setze ich ihnen eine Frist für einen Waffenstillstand, und sie lassen mich mit den Menschen gewähren: Wenn ich die Oberhand gewinne, können sie, wenn sie wollen, in das eintreten, worin die Menschen eingetreten sind; und wenn nicht, haben sie eine Atempause gewonnen. Wenn sie sich aber weigern, so schwöre ich bei Dem, in Dessen Hand meine Seele liegt: Ich werde gewiss für diese meine Sache kämpfen, bis meine Halsschlagader durchtrennt wird, und Allah wird Seinen Befehl unausweichlich zur Vollendung bringen!“ Da sagte Budayl: „Ich werde ihnen übermitteln, was du sagst.“ So ging er zu den Quraisch und sagte: „Wir kommen von diesem Mann zu euch und hörten ihn Worte sprechen; wenn ihr wollt, dass wir sie euch vortragen, tun wir es.“ Da sagten die Toren unter ihnen: „Wir haben kein Bedürfnis daran, dass du uns etwas von ihm erzählst!“ Die Besonnenen unter ihnen sagten jedoch: „Lass hören, was du ihn sagen hörtest!“ Er sagte: „Ich hörte ihn dies und jenes sagen“, und trug ihnen vor, was der Prophet (Friede sei auf ihm) gesagt hatte. Da stand ‘Urwah ibn Mas‘ud auf und sprach: „O mein Volk, bin ich nicht wie ein Vater für euch?“ Sie sagten: „Doch.“ Er sprach: „Und seid ihr nicht wie Kinder für mich?“ Sie sagten: „Doch.“ Er sprach: „Hegt ihr denn irgendeinen Verdacht gegen mich?“ Sie sagten: „Nein.“ Er sprach: „Wisst ihr denn nicht, dass ich die Leute von ‘Ukaz aufrief, euch beizustehen, und als sie sich weigerten, kam ich selbst mit meiner Familie, meinen Kindern und denjenigen, die mir gehorchten, zu euch?“ Sie sagten: „Gewiss.“ Er sprach: „Wahrlich, dieser Mann hat euch einen vernünftigen Vorschlag unterbreitet, so nehmt ihn an und lasst mich zu ihm gehen!“ Sie sagten: „Geh zu ihm!“ Da begab er sich zum Propheten (Friede sei auf ihm) und sprach mit ihm. Der Prophet (Friede sei auf ihm) sagte zu ihm Ähnliches wie das, was er zu Budayl gesagt hatte. Da sagte ‘Urwah: „O Muhammad, sag mir: Wenn du dein eigenes Volk vernichtest, hast du je von einem Araber vor dir gehört, der sein eigenes Volk auslöschte? Wenn es aber anders ausgeht, so sehe ich bei Allah Gesichter und eine bunte Schar von Leuten, die wohl flieht und dich im Stich lässt!“ Da rief Abu Bakr ihm zu: „Sauge doch an der Klitoris von al-Lat! Sollen wir etwa vor ihm fliehen und ihn im Stich lassen?“ ‘Urwah fragte: „Wer ist dieser?“ Sie sagten: „Abu Bakr.“ Er sprach: „Bei Dem, in Dessen Hand meine Seele liegt: Wäre nicht eine Wohltat gewesen, die du mir einst erwiesen hast und die ich dir noch nicht vergolten habe, so hätte ich dir darauf geantwortet!“ Während ‘Urwah mit dem Propheten (Friede sei auf ihm) sprach, fasste er immer wieder nach dessen Bart. Al-Mughirah ibn Schu‘bah stand mit gezogenem Schwert und behelmt am Haupte des Propheten (Friede sei auf ihm). Wann immer ‘Urwah seine Hand nach dem Bart des Propheten (Friede sei auf ihm) ausstreckte, schlug al-Mughirah mit dem Knauf des Schwertes auf seine Hand und sagte: „Halte deine Hand vom Bart des Gesandten Allahs (Friede sei auf ihm) fern!“ Da hob ‘Urwah seinen Kopf und fragte: „Wer ist dieser?“ Sie sagten: „Al-Mughirah ibn Schu‘bah.“ Da sagte ‘Urwah: „O Verräter! Mühe ich mich nicht noch immer ab, um für deinen Verrat Sühne zu leisten?“ – denn al-Mughirah hatte in der Zeit der Gahiliyyah eine Schar von Gefährten begleitet, sie getötet und ihr Vermögen an sich genommen; dann kam er und nahm den Islam an. Da hatte der Prophet (Friede sei auf ihm) zu ihm gesagt: „Was den Islam betrifft, so nehme ich ihn an; was aber das Vermögen betrifft, so habe ich damit nichts zu tun.“ Dann begann ‘Urwah, die Gefährten des Propheten (Friede sei auf ihm) aufmerksam mit den Augen zu mustern: Bei Allah, wann immer der Gesandte Allahs (Friede sei auf ihm) sich räusperte und Auswurf von sich gab, fiel dieser sogleich in die Handfläche eines Mannes unter ihnen, der ihn sich über sein Gesicht und seine Haut rieb. Wenn er ihnen etwas befahl, beeilten sie sich, seinen Befehl auszuführen. Wenn er die Gebetswaschung vollzog, kämpften sie beinahe um das übriggebliebene Wasser seiner Waschung. Und wenn er sprach, senkten sie ihre Stimmen in seiner Gegenwart und sahen ihn aus Ehrfurcht nicht starr an. Als ‘Urwah zu seinen Gefährten zurückkehrte, sprach er: „O mein Volk! Bei Allah, ich bin als Gesandter vor Könige getreten, ich trat vor den Kaiser von Byzanz, vor Chosrau von Persien und vor den Negus von Abessinien; doch bei Allah, niemals habe ich einen König gesehen, den seine Gefährten derart ehren, wie die Gefährten Muhammads Muhammad (Friede sei auf ihm) ehren! Bei Allah, wenn er sich räuspert, fällt sein Auswurf ausnahmslos in die Hand eines Mannes unter ihnen, der ihn sich über sein Gesicht und seine Haut streicht. Wenn er ihnen einen Befehl erteilt, beeilen sie sich, ihn auszuführen. Wenn er die Waschung vollzieht, ringen sie fast um das Wasser seiner Waschung. Wenn er spricht, dämpfen sie ihre Stimmen vor ihm, und sie blicken ihn aus Ehrfurcht nicht fest an. Er hat euch einen vernünftigen Vorschlag unterbreitet, so nehmt ihn an!“ Da sprach ein Mann von den Banu Kinanah: „Lasst mich zu ihm gehen!“ Sie sagten: „Geh zu ihm!“ Als er vor dem Propheten (Friede sei auf ihm) und seinen Gefährten erschien, sprach der Gesandte Allahs (Friede sei auf ihm): „Dies ist Soundso; er gehört zu einem Volk, das die Opfertiere verehrt, so treibt sie vor ihm her!“ Da trieb man die Opfertiere vor ihm her, und die Leute empfingen ihn mit dem Talbiyah-Ruf. Als er dies sah, rief er aus: „Gepriesen sei Allah! Diesen Leuten darf der Zutritt zum Hause Allahs keineswegs verwehrt werden!“ Als er zu seinen Gefährten zurückkehrte, sagte er: „Ich habe gesehen, dass die Opfertiere bereits mit Kränzen geschmückt und gekennzeichnet sind; ich halte es für unrecht, sie vom Hause fernzuhalten.“ Da stand ein Mann unter ihnen namens Mikraz ibn Hafs auf und sagte: „Lasst mich zu ihm gehen!“ Sie sagten: „Geh zu ihm!“ Als er sich ihnen näherte, sprach der Prophet (Friede sei auf ihm): „Dies ist Mikraz, und er ist ein frevelhafter Mann.“ Er begann mit dem Propheten (Friede sei auf ihm) zu verhandeln. Während er mit ihm sprach, traf plötzlich Suhayl ibn ‘Amr ein. Ma‘mar sagte: Ayyub teilte mir von ‘Ikrimah mit, dass der Prophet (Friede sei auf ihm), als Suhayl ibn ‘Amr herantrat, sprach: „Nun ist eure Angelegenheit für euch leicht geworden!“ Ma‘mar sagte: Az-Zuhri sagte in seiner Überlieferung: Suhayl ibn ‘Amr kam und sprach: „Auf, schreibe einen Vertrag zwischen uns und dir nieder!“ Da rief der Prophet (Friede sei auf ihm) den Schreiber herbei und sprach: „Schreibe: Im Namen Allahs, des Allerbarmers, des Barmherzigen (Bismi-Llahi r-Rahmani r-Rahim).“ Da sprach Suhayl: „Was den Allerbarmer betrifft, so weiß ich bei Allah nicht, was das ist; schreibe vielmehr: ‚In Deinem Namen, o Allah (Bismika Allahumma)‘, wie du es zuvor zu schreiben pflegtest!“ Da sprachen die Muslime: „Bei Allah, wir schreiben nichts anderes als: Im Namen Allahs, des Allerbarmers, des Barmherzigen!“ Doch der Prophet (Friede sei auf ihm) sprach: „Schreibe: In Deinem Namen, o Allah.“ Dann sprach er: „Dies ist, worauf sich Muhammad, der Gesandte Allahs, geeinigt hat.“ Da sprach Suhayl: „Bei Allah, wenn wir wüssten, dass du der Gesandte Allahs bist, hätten wir dich nicht vom Hause abgehalten und dich nicht bekämpft; schreibe vielmehr: Muhammad, der Sohn von ‘Abdullah!“ Da sprach der Prophet (Friede sei auf ihm): „Bei Allah, ich bin wahrlich der Gesandte Allahs, selbst wenn ihr mich der Lüge bezichtigt! Schreibe: Muhammad ibn ‘Abdullah.“ Az-Zuhri sagte: Dies tat er wegen seines Wortes: „Was immer sie von mir an einer Bedingung verlangen, durch die sie die geheiligten Stätten Allahs achten, werde ich ihnen gewähren.“ Dann sprach der Prophet (Friede sei auf ihm): „Unter der Bedingung, dass ihr uns ungehindert zum Hause gelangen lasst, sodass wir es umrunden können.“ Da sprach Suhayl: „Bei Allah, die Araber sollen keinesfalls sagen, wir hätten uns dazu zwingen lassen; vielmehr soll dies erst im nächsten Jahr geschehen!“ So wurde es niedergeschrieben. Dann sprach Suhayl: „Und unter der Bedingung, dass, wenn ein Mann von uns zu dir kommt – selbst wenn er deine Religion angenommen hat –, du ihn an uns zurückstellst.“ Da riefen die Muslime: „Gepriesen sei Allah! Wie soll jemand, der als Muslim zu uns kommt, an die Götzendiener zurückgegeben werden?“ Während sie noch darüber sprachen, kam plötzlich Abu Jandal ibn Suhayl ibn ‘Amr in Ketten herbeigeschleift; er war aus dem Tal von Mekka entkommen und hatte sich mitten unter die Muslime geworfen. Da sprach Suhayl: „Dies ist der Erste, über den ich den Vertrag mit dir schließe, dass du ihn an mich zurückgibst!“ Da sprach der Prophet (Friede sei auf ihm): „Wir haben das Schriftstück doch noch gar nicht vollendet!“ Jener sagte: „Bei Allah, dann schließe ich mit dir über überhaupt nichts mehr Frieden!“ Da sprach der Prophet (Friede sei auf ihm): „So überlasse ihn mir doch aus Gefälligkeit!“ Jener sagte: „Ich überlasse ihn dir keineswegs!“ Der Prophet sprach: „Doch, tu es!“ Jener erwiderte: „Ich tue es nicht!“ Da sagte Mikraz: „Was uns betrifft, so haben wir ihn dir überlassen.“ Da rief Abu Jandal: „O ihr Muslime! Soll ich an die Götzendiener zurückgegeben werden, wo ich doch als Muslim zu euch gekommen bin? Seht ihr denn nicht, was ich erlitten habe?“ – und er war auf dem Wege Allahs grausam gefoltert worden. ‘Umar ibn al-Khattab sagte: Da ging ich zum Propheten Allahs (Friede sei auf ihm) und sagte: „Bist du nicht wahrhaftig der Prophet Allahs?“ Er sprach: „Doch.“ Ich sagte: „Sind wir nicht auf der Wahrheit und unser Feind auf der Falschheit?“ Er sprach: „Doch.“ Ich sagte: „Warum geben wir dann unserer Religion eine solche Demütigung preis?“ Er sprach: „Ich bin der Gesandte Allahs, und ich bin Ihm nicht ungehorsam, und Er ist mein Beistand.“ Ich sagte: „Hast du uns denn nicht gesagt, dass wir zum Hause kommen und es umrunden werden?“ Er sprach: „Gewiss; doch habe ich dir gesagt, dass wir noch in diesem Jahr zu ihm kommen?“ Ich sagte: „Nein.“ Er sprach: „Du wirst gewiss zu ihm kommen und es umrunden!“ ‘Umar sagte: Dann ging ich zu Abu Bakr und sagte: „O Abu Bakr, ist er nicht wahrhaftig der Prophet Allahs?“ Er sagte: „Doch.“ Ich sagte: „Sind wir nicht auf der Wahrheit und unser Feind auf der Falschheit?“ Er sagte: „Doch.“ Ich sagte: „Warum geben wir dann unserer Religion eine solche Demütigung preis?“ Da sprach Abu Bakr: „O Mann, er ist der Gesandte Allahs (Friede sei auf ihm); er ist seinem Herrn nicht ungehorsam, und Er ist sein Beistand! Halte dich daher fest an seine Weisung, denn bei Allah, er ist auf der Wahrheit!“ Ich sagte: „Hat er uns denn nicht gesagt, dass wir zum Hause kommen und es umrunden werden?“ Er sagte: „Gewiss; doch hat er dir gesagt, dass du noch in diesem Jahr zu ihm kommst?“ Ich sagte: „Nein.“ Er sagte: „Du wirst gewiss zu ihm kommen und es umrunden!“ Az-Zuhri sagte: ‘Umar sagte: „Danach verrichtete ich viele gute Werke als Buße für mein damaliges Verhalten.“ Als das Niederschreiben des Vertrages abgeschlossen war, sprach der Gesandte Allahs (Friede sei auf ihm) zu seinen Gefährten: „Steht auf, schächtet eure Opfertiere und rasiert eure Köpfe!“ Doch bei Allah, kein einziger Mann von ihnen stand auf, obwohl er dies dreimal wiederholte. Als niemand von ihnen aufstand, ging er hinein zu Umm Salamah und berichtete ihr, was er von den Leuten erlebt hatte. Da sprach Umm Salamah: „O Prophet Allahs, wünschst du dies? Geh hinaus und sprich zu keinem von ihnen auch nur ein einziges Wort, bis du dein Opferkamel geschlachtet und deinen Barbier gerufen hast, damit er deinen Kopf rasiert!“ Da ging er hinaus und sprach zu niemandem von ihnen ein Wort, bis er dies getan hatte: Er schächtete seine Opfertiere und rief seinen Barbier, der seinen Kopf rasierte. Als die Gefährten dies sahen, sprangen sie auf, schächteten ihre Opfertiere und begannen einander gegenseitig die Köpfe zu rasieren, sodass sie sich vor Kummer und Bedrängnis beinahe gegenseitig erschlagen hätten. Danach kamen gläubige Frauen zu ihm herüber; da sandte Allah der Erhabene herab: „O die ihr glaubt! Wenn gläubige Frauen als Auswanderinnen zu euch kommen, so prüft sie...“ bis zu Seinen Worten: „...am Eheband mit den ungläubigen Frauen festzuhalten“ (Sure 60, Vers 10 bis 10). An jenem Tag verstieß ‘Umar zwei Frauen, die er noch im Götzendienst geheiratet hatte; Mu‘awiyah ibn Abi Sufyan heiratete die eine von ihnen, und Safwan ibn Umayyah heiratete die andere. Dann kehrte der Prophet (Friede sei auf ihm) nach Medina zurück. Da kam Abu Basir zu ihm, ein muslimischer Mann von den Quraisch. Die Quraisch sandten zwei Männer hinter ihm her und sagten: „Erfülle den Vertrag, den du mit uns geschlossen hast!“ Da übergab er Abu Basir an die beiden Männer. Sie zogen mit ihm aus, bis sie Dhu l-Hulayfah erreichten, wo sie abstiegen, um von ihren Datteln zu essen. Da sagte Abu Basir zu einem der beiden Männer: „Bei Allah, ich sehe, dass dein Schwert ausgezeichnet ist, o Soundso!“ Da zog der andere es heraus und sagte: „Ja, bei Allah, es ist vortrefflich; ich habe es erprobt und abermals erprobt!“ Abu Basir sagte: „Lass es mich betrachten!“ Da reichte er es ihm, und Abu Basir hieb auf ihn ein, bis er tot war. Der andere Mann floh in wilder Hast, bis er Medina erreichte, und stürzte in die Moschee. Als der Gesandte Allahs (Friede sei auf ihm) ihn erblickte, sprach er: „Dieser Mann hat wahrlich etwas Schreckliches gesehen!“ Als er den Propheten (Friede sei auf ihm) erreichte, rief er: „Bei Allah, mein Gefährte wurde getötet, und auch ich werde getötet werden!“ Da kam Abu Basir herbei und sagte: „O Prophet Allahs, bei Allah, Allah hat deine Verpflichtung erfüllt: Du hast mich an sie ausgeliefert, und dann hat Allah mich vor ihnen gerettet!“ Da rief der Prophet (Friede sei auf ihm) aus: „Wehe seiner Mutter! Ein wahrer Schürer des Krieges, wenn er nur Gefährten hätte!“ Als Abu Basir dies hörte, begriff er, dass der Prophet ihn erneut an die Ungläubigen ausliefern würde. So zog er eilends davon, bis er die Meeresküste erreichte. Da entkam auch Abu Jandal ibn Suhayl und schloss sich Abu Basir an. Von da an entkam kein Mann von den Quraisch, der den Islam angenommen hatte, ohne sich Abu Basir anzuschließen, bis sich eine ganze Schar um ihn versammelt hatte. Bei Allah, wann immer sie von einer Karawane der Quraisch hörten, die nach Scham (Syrien) aufbrach, lauerten sie ihr auf, töteten ihre Männer und bemächtigten sich ihrer Güter. Da sandten die Quraisch flehentlich Boten zum Propheten (Friede sei auf ihm) und beschworen ihn bei Allah und der Blutsverwandtschaft, jene Leute zu sich zu rufen, und wer immer zu ihm käme, solle in Sicherheit sein. Da sandte der Prophet (Friede sei auf ihm) nach ihnen. Daraufhin sandte Allah der Erhabene herab: „Und Er ist es, Der ihre Hände von euch und eure Hände von ihnen im Tal von Mekka zurückgehalten hat, nachdem Er euch den Sieg über sie verliehen hatte...“ (Sure 48, Vers 24 bis 24) bis zu Seinen Worten: „...den Hochmut, den Hochmut der Gahiliyyah“ (Sure 48, Vers 1 bis 1). Und ihr Hochmut bestand darin, dass sie sich weigerten anzuerkennen, dass er der Prophet Allahs ist, und sich weigerten, ‚Im Namen Allahs, des Allerbarmers, des Barmherzigen‘ anzuerkennen, und sie daran hinderten, das Haus der Kaaba zu erreichen.",

  // 2: ff8ea6cf-c887-4713-8350-687ca96ce960 (Herakleios & Abu Sufyan)
  "Ibrahim ibn Hamzah berichtete uns: Ibrahim ibn Sa‘d berichtete uns von Salih ibn Kaysan, von Ibn Schihab, von ‘Ubaydullah ibn ‘Abdullah ibn ‘Utbah, von ‘Abdullah ibn ‘Abbas (möge Allah mit beiden zufrieden sein), der ihm berichtete, dass der Gesandte Allahs (Friede sei auf ihm) an den byzantinischen Kaiser (Kaisar) schrieb und ihn zum Islam einlud. Er sandte sein Schreiben mit Dihyah al-Kalbi zu ihm und trug ihm auf, es dem Statthalter von Busra zu übergeben, damit dieser es an den Kaiser weiterleite. Der Kaiser war damals aus Dankbarkeit für das, was Allah ihm verliehen hatte – als Allah die persischen Heere von ihm abgewendet hatte –, zu Fuß von Homs nach Iliya (Jerusalem) gepilgert. Als das Schreiben des Gesandten Allahs (Friede sei auf ihm) beim Kaiser eintraf, sprach er, nachdem er es gelesen hatte: „Sucht mir hier jemanden aus seinem Volk, damit ich ihn über den Gesandten Allahs (Friede sei auf ihm) befrage!“ Ibn ‘Abbas sagte: Abu Sufyan ibn Harb berichtete mir, dass er sich damals mit einer Gruppe von Männern der Quraisch in Scham (Syrien) befand, wo sie während des Waffenstillstands, den der Gesandte Allahs (Friede sei auf ihm) mit den Ungläubigen der Quraisch geschlossen hatte, als Kaufleute unterwegs waren. Abu Sufyan sagte: Der Bote des Kaisers fand uns in einer Gegend von Scham und führte mich und meine Gefährten mit sich, bis wir nach Iliya kamen. Wir wurden vor den Kaiser geführt, der in seinem Herrschersitz mit seiner Krone saß, umgeben von den Großen des byzantinischen Reiches. Da sprach er zu seinem Dolmetscher: „Frage sie, wer von ihnen der Nächste in der Verwandtschaft zu diesem Mann ist, der behauptet, ein Prophet zu sein!“ Abu Sufyan sagte: Ich antwortete: „Ich bin der Nächste von ihnen in der Verwandtschaft.“ Er fragte: „Welcher Verwandtschaftsgrad besteht zwischen dir und ihm?“ Ich sagte: „Er ist mein Vetter väterlicherseits.“ Und in jener Karawane war damals niemand von den Banu ‘Abd Manaf außer mir. Da sprach der Kaiser: „Bringt ihn näher zu mir!“ Und er befahl, meine Gefährten hinter meinem Rücken an meinen Schultern aufzustellen. Dann sprach er zu seinem Dolmetscher: „Sage seinen Gefährten: Ich werde diesen Mann über jenen befragen, der behauptet, ein Prophet zu sein; wenn er lügt, so bezichtigt ihn der Lüge!“ Abu Sufyan sagte: Bei Allah, hätte ich mich nicht geschämt, dass meine Gefährten eine Lüge über mich weitertragen würden, so hätte ich über ihn gelogen, als der Kaiser mich befragte! Doch ich schämte mich davor, dass sie eine Lüge von mir weitererzählen würden, und so sagte ich die Wahrheit. Da sprach der Kaiser zu seinem Dolmetscher: „Frage ihn: Welchen Rang hat seine Abstammung unter euch?“ Ich sagte: „Er besitzt unter uns eine edle Abstammung.“ Er fragte: „Hat jemals jemand von euch diese Behauptung vor ihm aufgestellt?“ Ich sagte: „Nein.“ Er fragte: „Habt ihr ihn jemals der Lüge bezichtigt, bevor er dies behauptete?“ Ich sagte: „Nein.“ Er fragte: „War einer seiner Vorväter ein König?“ Ich sagte: „Nein.“ Er fragte: „Folgen ihm die Vornehmen unter den Menschen oder die Schwachen?“ Ich sagte: „Vielmehr die Schwachen unter ihnen.“ Er fragte: „Werden sie mehr oder weniger?“ Ich sagte: „Sie werden mehr.“ Er fragte: „Fällt jemand von ihnen aus Unmut von seiner Religion ab, nachdem er in sie eingetreten ist?“ Ich sagte: „Nein.“ Er fragte: „Bricht er Verträge?“ Ich sagte: „Nein; wir befinden uns derzeit in einem Waffenstillstand mit ihm, und wir fürchten, dass er uns verraten könnte.“ Abu Sufyan sagte: Ich fand keine Möglichkeit, auch nur ein einziges negatives Wort gegen ihn einzufügen, außer diesem Satz, aus Furcht, dass etwas anderes gegen mich verwendet würde. Der Kaiser fragte: „Habt ihr ihn bekämpft oder hat er euch bekämpft?“ Ich sagte: „Ja.“ Er fragte: „Wie verlief der Krieg zwischen euch und ihm?“ Ich sagte: „Der Krieg zwischen uns und ihm wogte hin und her; einmal hatte er den Sieg über uns, und einmal hatten wir den Sieg über ihn.“ Er fragte: „Was befiehlt er euch?“ Ich sagte: „Er befiehlt uns, Allah allein anzubeten und Ihm nichts beizugesellen, und er verbietet uns, das anzubeten, was unsere Vorväter anbeteten; und er befiehlt uns das Gebet, das Almosengeben, die Keuschheit, das Halten von Verträgen und das Zurückgeben von Anvertrautem.“ Als ich dies gesagt hatte, sprach der Kaiser zu seinem Dolmetscher: „Sprich zu ihm: Ich fragte dich nach seiner Abstammung unter euch, und du gabst an, dass er von edler Abstammung ist; ebenso werden die Gesandten stets inmitten des edelsten Adels ihres Volkes entsandt. Und ich fragte dich, ob jemals jemand von euch diese Behauptung vor ihm aufgestellt habe, und du verneintest es; da sagte ich mir: Hätte jemand vor ihm diese Behauptung aufgestellt, so hätte ich gesagt: Ein Mann, der den Worten eines früheren Mannes nacheifert! Und ich fragte dich, ob ihr ihn vor seiner Behauptung jemals der Lüge bezichtigt hattet, und du verneintest es; da wusste ich wohl, dass er nicht die Menschen von Lügen verschonen würde, um dann eine Lüge gegen Allah zu erfinden! Und ich fragte dich, ob einer seiner Vorväter ein König gewesen sei, und du verneintest es; da sagte ich mir: Wäre einer seiner Vorväter ein König gewesen, hätte ich gesagt: Ein Mann, der das Königreich seiner Väter zurückfordert! Und ich fragte dich, ob die Vornehmen unter den Menschen ihm folgen oder ihre Schwachen, und du gabst an, dass die Schwachen ihm folgen; und sie sind es, die den Gesandten folgen! Und ich fragte dich, ob sie zunehmen oder abnehmen, und du gabst an, dass sie zunehmen; und so verhält es sich mit dem Glauben, bis er vollendet ist! Und ich fragte dich, ob jemand aus Unmut von seiner Religion abfällt, nachdem er in sie eingetreten ist, und du verneintest es; und so ist der Glaube, wenn seine Heiterkeit sich mit den Herzen vermengt: Niemand empfindet danach Unmut! Und ich fragte dich, ob er Verträge bricht, und du verneintest es; und so sind die Gesandten: Sie begehen keinen Verrat! Und ich fragte dich, ob ihr ihn bekämpftet und er euch bekämpfte, und du gabst an, dass der Krieg zwischen euch hin und her wogte; und so werden die Gesandten geprüft, doch der endgültige Sieg gehört ihnen! Und ich fragte dich, was er euch befiehlt, und du gabst an, dass er euch befiehlt, Allah anzubeten und Ihm nichts beizugesellen, euch verbietet, das anzubeten, was eure Vorväter anbeteten, und euch das Gebet, die Wahrhaftigkeit, die Keuschheit, die Vertragstreue und das Erfüllen von Anvertrautem gebietet.“ Dann sprach der Kaiser: „Dies ist in der Tat die Beschreibung eines Propheten! Ich wusste wohl, dass er erscheinen würde, doch ich dachte nicht, dass er aus eurer Mitte sein würde. Wenn das, was du sagst, wahr ist, so wird er gar bald den Boden unter diesen meinen beiden Füßen beherrschen! Wenn ich wüsste, dass ich zu ihm gelangen könnte, hätte ich gewiss die Mühe auf mich genommen, ihm zu begegnen; und wäre ich bei ihm, würde ich seine Füße waschen!“ Abu Sufyan sagte: Dann ließ der Kaiser das Schreiben des Gesandten Allahs (Friede sei auf ihm) herbeibringen, und es wurde verlesen. Darin stand: ‚Im Namen Allahs, des Allerbarmers, des Barmherzigen. Von Muhammad, dem Diener Allahs und Seinem Gesandten, an Herakleios, den Herrscher der Byzantiner: Friede sei auf dem, der der Rechtleitung folgt! Sodann: Ich lade dich mit dem Ruf des Islam ein: Nimm den Islam an, so wirst du Heil erlangen; nimm den Islam an, so wird Allah dir deinen Lohn zweifach vergelten! Wenn du dich aber abwendest, so lastet auf dir die Sünde der Untertanen (der Arisiyyin). „O Leute der Schrift, kommt herbei zu einem gemeinsamen Wort zwischen uns und euch: dass wir niemandem dienen außer Allah und Ihm nichts beigesellen und dass sich nicht die einen von uns die anderen zu Herren nehmen neben Allah! Wenn sie sich aber abwenden, so sprecht: Bezeugt, dass wir Muslime (Gottergebene) sind!“ (Sure 3, Vers 64 bis 64).‘ Abu Sufyan sagte: Als der Kaiser seine Rede beendet hatte, wurden die Stimmen der byzantinischen Vornehmen um ihn her laut, und ein gewaltiger Lärm erhob sich, sodass ich nicht mehr verstand, was sie sagten. Man befahl uns hinauszugehen, und wir wurden hinausgeführt. Als ich mit meinen Gefährten allein war, sagte ich zu ihnen: ‚Wahrlich, die Angelegenheit des Sohnes von Abu Kabscha ist gewaltig geworden! Selbst der König der Banu al-Asfar (der Byzantiner) fürchtet ihn!‘ Abu Sufyan sagte: Bei Allah, ich blieb gedemütigt und war fest davon überzeugt, dass seine Sache siegreich sein würde, bis Allah den Islam in mein Herz einkehren ließ, obwohl ich ihn zuvor verabscheut hatte.",

  // 3: ff81a79e-b0c0-43bc-b178-c9b1016aeb40
  "Abu l-Walid berichtete uns: Salm ibn Zarir berichtete uns: Ich hörte Abu Raja’ sagen: ‘Imran ibn Husayn berichtete uns, dass sie mit dem Propheten (Friede sei auf ihm) auf einer Reise waren. Sie zogen die ganze Nacht hindurch. Gegen Ende der Nacht machten sie Rast, und der Schlaf übermannte sie, bis die Sonne hoch am Himmel stand. Der Erste, der aus seinem Schlaf erwachte, war Abu Bakr; und der Gesandte Allahs (Friede sei auf ihm) wurde niemals aus seinem Schlaf geweckt, bis er von selbst erwachte. Dann erwachte ‘Umar. Da setzte sich Abu Bakr an das Haupt des Propheten (Friede sei auf ihm) und begann laut den Takbir („Allahu Akbar“) zu rufen und seine Stimme zu erheben, bis der Prophet (Friede sei auf ihm) erwachte. Da stieg er ab und betete mit uns das Morgengebet. Ein Mann aus den Leuten hielt sich abseits und betete nicht mit uns. Als der Prophet sein Gebet beendet hatte, sprach er: „O Soundso, was hielt dich davon ab, mit uns zu beten?“ Der Mann sagte: „Mich traf der Zustand der rituellen Unreinheit (Djanabah).“ Da befahl er ihm, die Trockenwaschung (Tayammum) mit reiner Erde zu vollziehen, woraufhin jener betete. Dann stellte mich der Gesandte Allahs (Friede sei auf ihm) unter die Reiter vor sich. Wir litten unter heftigem Durst. Während wir ritten, trafen wir auf eine Frau, die ihre Beine zwischen zwei großen Wasserschläuchen auf ihrem Kamel baumeln ließ. Wir fragten sie: „Wo gibt es Wasser?“ Sie sagte: „Es gibt kein Wasser.“ Wir fragten: „Wie weit ist der Weg von deinen Angehörigen bis zum Wasser?“ Sie sagte: „Einen Tag und eine Nacht.“ Da sagten wir: „Komm mit zum Gesandten Allahs (Friede sei auf ihm)!“ Sie fragte: „Und wer ist der Gesandte Allahs?“ Wir ließen ihr keine Wahl, sondern führten sie zum Propheten (Friede sei auf ihm). Sie erzählte ihm dasselbe, was sie uns erzählt hatte, erwähnte jedoch zusätzlich, dass sie eine Witwe mit Waisen sei. Da befahl er, ihre beiden Wasserschläuche herabzunehmen, und er strich über ihre Öffnungen. Da tranken wir Durstigen – vierzig Männer –, bis wir alle vollauf gesättigt waren! Und wir füllten jeden Wasserschlauch und jedes Gefäß, das wir bei uns hatten, tränkten jedoch kein einziges Kamel. Ihre Wasserschläuche platzten beinahe vor Fülle! Dann sprach er: „Bringt herbei, was ihr habt!“ Da sammelte man für sie Brocken von Brot und Datteln. Als sie zu ihren Angehörigen zurückkehrte, sagte sie: „Ich bin entweder dem größten Zauberer unter den Menschen begegnet, oder er ist wahrhaftig ein Prophet, wie sie behaupten!“ Und durch jene Frau leitete Allah jene Sippe recht, sodass sie allesamt den Islam annahmen.",

  // 4: 0677d032-8b49-4151-ab59-cd80f9d17303
  "‘Abdullah ibn Yusuf berichtete uns: Malik teilte uns mit, von Ishaq ibn ‘Abdullah ibn Abi Talhah, der Anas ibn Malik sagen hörte: Abu Talhah sagte zu Umm Sulaym: „Ich hörte die Stimme des Gesandten Allahs (Friede sei auf ihm) schwach klingen; ich erkenne den Hunger darin. Hast du etwas daheim?“ Sie sagte: „Ja.“ Da holte sie einige Gerstengerstenbrote hervor, nahm ihren Schleier, wickelte das Brot in einen Teil davon und steckte es mir unter das Gewand, band einen Teil um mich und schickte mich zum Gesandten Allahs (Friede sei auf ihm). Ich ging damit hin und fand den Gesandten Allahs (Friede sei auf ihm) sitzend in der Moschee inmitten der Leute. Ich stellte mich zu ihnen. Da sprach der Gesandte Allahs (Friede sei auf ihm) zu mir: „Hat Abu Talhah dich gesandt?“ Ich sagte: „Ja.“ Er fragte: „Mit einer Mahlzeit?“ Ich sagte: „Ja.“ Da sprach der Gesandte Allahs (Friede sei auf ihm) zu den Leuten bei ihm: „Steht auf!“ Er brach auf, und ich lief vor ihnen her, bis ich zu Abu Talhah kam und es ihm berichtete. Da sprach Abu Talhah: „O Umm Sulaym, der Gesandte Allahs (Friede sei auf ihm) ist mit den Menschen gekommen, und wir haben nichts, womit wir sie speisen könnten!“ Sie sprach: „Allah und Sein Gesandter wissen es am besten.“ Da ging Abu Talhah hinaus, bis er den Gesandten Allahs (Friede sei auf ihm) traf. Der Gesandte Allahs (Friede sei auf ihm) trat mit Abu Talhah ein und sprach: „Bring herbei, was du hast, o Umm Sulaym!“ Da brachte sie jenes Brot herbei. Der Gesandte Allahs (Friede sei auf ihm) befahl, es in Brocken zu brechen. Umm Sulaym drückte einen kleinen Schlauch mit Butterschmalz darüber aus und würzte es damit. Dann sprach der Gesandte Allahs (Friede sei auf ihm) darüber, was immer Allah wollte, dass er sprach. Dann sagte er: „Lasst zehn eintreten!“ Abu Talhah ließ sie eintreten. Sie aßen, bis sie satt waren, und gingen wieder hinaus. Dann sprach er: „Lasst zehn eintreten!“ Abu Talhah ließ sie eintreten. Sie aßen, bis sie satt waren, und gingen hinaus. Dann sprach er: „Lasst zehn eintreten!“ Abu Talhah ließ sie eintreten. Sie aßen, bis sie satt waren, und gingen hinaus. Dann sprach er: „Lasst zehn eintreten!“ So aßen alle Leute, bis sie vollauf satt waren; und die Schar zählte siebzig oder achtzig Männer.",

  // 5: 08bbef1a-30e4-4d03-b236-790cd3bf9bf9
  "Musa ibn Isma‘il berichtete uns: al-Mu‘tamir berichtete uns von seinem Vater: Abu ‘Uthman berichtete uns, dass ‘Abd ar-Rahman ibn Abi Bakr (möge Allah mit beiden zufrieden sein) ihm berichtete, dass die Gefährten der Suffah mittellose arme Leute waren. Der Prophet (Friede sei auf ihm) sprach einst: „Wer Speise für zwei hat, der nehme einen dritten mit; und wer Speise für vier hat, der nehme einen fünften oder sechsten mit“ – oder wie er es sagte. Abu Bakr brachte drei Leute mit sich, und der Prophet (Friede sei auf ihm) nahm zehn mit sich. Abu Bakr kam mit dreien. Er sagte: Bei uns waren ich, mein Vater und meine Mutter – und ich weiß nicht, ob er auch sagte: meine Frau und mein Diener, die zwischen unserem Haus und dem Hause von Abu Bakr lebten. Abu Bakr aß das Abendessen beim Propheten (Friede sei auf ihm) und verweilte dort, bis er das Nachtgebet (‘Ischa’) betete. Dann kehrte er zurück und blieb, bis der Gesandte Allahs (Friede sei auf ihm) zu Abend gegessen hatte. Er kam erst nach Hause, als von der Nacht vergangen war, was Allah wollte. Da sprach seine Frau zu ihm: „Was hielt dich von deinen Gästen ab?“ Er fragte: „Habt ihr ihnen denn nicht das Abendessen serviert?“ Sie sprach: „Sie weigerten sich, bis du kämest; man bot es ihnen an, doch sie lehnten ab.“ Da ging ich davon und versteckte mich. Da rief Abu Bakr: „O du Taugenichts!“, und schimpfte und wetterte gegen mich. Dann sagte er zu den Gästen: „Esst!“, und schwor: „Bei Allah, niemals werde ich davon essen!“ Doch bei Allah, wann immer wir einen Bissen nahmen, wuchs die Speise von unten her nach, bis sie mehr wurde als zuvor, und alle satt wurden; und sie war am Ende reichlicher als zu Beginn! Abu Bakr blickte darauf und sah, dass sie genauso viel oder noch mehr war. Da sprach er zu seiner Frau: „O Schwester der Banu Firas, was ist das?“ Sie sprach: „Nein, bei der Freude meiner Augen, sie ist jetzt dreimal mehr als zuvor!“ Da aß Abu Bakr davon und sprach: „Jener Schwur kam gewiss vom Satan“ – womit er seinen Schwur meinte. Dann aß er einen Bissen davon und trug die Speise zum Propheten (Friede sei auf ihm). Sie blieb bei ihm bis zum Morgen. Zwischen uns und einem Volk bestand ein Waffenstillstandsvertrag, dessen Frist ablief. Da teilten wir uns in zwölf Gruppen auf, und jedem Mann von ihnen war eine Schar zugeteilt – Allah weiß am besten, wie viele bei jedem Mann waren –; er sandte die Speise mit ihnen, und sie aßen alle davon, oder wie er es sagte. Ein anderer Überlieferer sagte: Wir erfuhren dies durch die Anführer der Gruppen.",

  // 6: 5957ade3-d91a-4ec6-911d-14b7f5229d5c
  "Musa sagte: Salim ibn ‘Abdullah berichtete mir – und ich glaube, er überlieferte dies von Ibn ‘Umar –: Zayd ibn ‘Amr ibn Nufayl zog nach Scham (Syrien) aus, um nach der wahren Religion zu forschen und ihr zu folgen. Da traf er einen jüdischen Gelehrten und befragte ihn über ihre Religion. Er sagte: „Vielleicht nehme ich eure Religion an, so berichte mir von ihr!“ Da sprach der Gelehrte: „Du wirst unserer Religion nicht beitreten können, bevor du deinen Anteil am Zorn Allahs auf dich nimmst!“ Zayd sagte: „Ich fliehe doch gerade vor dem Zorn Allahs, und niemals werde ich irgendetwas vom Zorne Allahs auf mich laden, solange ich es vermag! Kannst du mir eine andere Religion weisen?“ Der Gelehrte sprach: „Ich kenne keine, es sei denn, du bist ein Hanif.“ Zayd fragte: „Und was ist ein Hanif?“ Er antwortete: „Die Religion Abrahams: Er war weder ein Jude noch ein Christ, und er betete niemanden an außer Allah allein.“ Da zog Zayd weiter und traf einen christlichen Gelehrten. Er befragte ihn auf ähnliche Weise, woraufhin dieser sprach: „Du wirst unserer Religion nicht beitreten können, bevor du deinen Anteil am Fluche Allahs auf dich nimmst!“ Zayd sagte: „Ich fliehe doch gerade vor dem Fluche Allahs, und niemals werde ich irgendetwas vom Fluche Allahs oder Seinem Zorne auf mich laden, solange ich es vermag! Kannst du mir eine andere Religion weisen?“ Der Gelehrte sprach: „Ich kenne keine, es sei denn, du bist ein Hanif.“ Zayd fragte: „Und was ist ein Hanif?“ Er antwortete: „Die Religion Abrahams: Er war weder ein Jude noch ein Christ, und er betete niemanden an außer Allah allein.“ Als Zayd sah, wie sie Abraham (Friede sei auf ihm) beschrieben, ging er hinaus ins Freie, erhob seine beiden Hände und rief: „O Allah, ich bezeuge vor Dir, dass ich der Religion Abrahams folge!“",

  // 7: d84791b3-8a4f-4959-8657-27cc5bb6fdeb
  "Abu n-Nu‘man berichtete uns: Abu ‘Awanah berichtete uns von Bayan Abu Bischr, von Qays ibn Abi Hazim, der sagte: Abu Bakr trat bei einer Frau vom Stamme Ahmas namens Zaynab ein. Er sah, dass sie kein Wort sprach, und fragte: „Warum spricht sie nicht?“ Sie sagten: „Sie hat die Pilgerfahrt vollzogen, während sie das Schweigen gelobt hat.“ Da sprach er zu ihr: „Sprich! Denn dies ist nicht erlaubt; dies gehört zu den Bräuchen der Gahiliyyah (der vorislamischen Unwissenheit)!“ Da sprach sie und fragte: „Wer bist du?“ Er sagte: „Ein Mann von den Auswanderern (Muhajirun).“ Sie fragte: „Von welchen Auswanderern?“ Er sagte: „Von den Quraisch.“ Sie fragte: „Aus welcher Sippe der Quraisch?“ Er sagte: „Du stellst aber viele Fragen! Ich bin Abu Bakr.“ Sie fragte: „Wie lange werden wir auf dieser guten Ordnung verweilen, die Allah uns nach der Zeit der Gahiliyyah gebracht hat?“ Er antwortete: „Ihr werdet darauf verweilen, solange eure Führer für euch rechtschaffen bleiben.“ Sie fragte: „Und wer sind die Führer?“ Er sagte: „Hatte dein Volk denn nicht Oberhäupter und Edle, die ihnen Befehle erteilten und denen sie gehorchten?“ Sie sagte: „Doch.“ Er sagte: „Jene sind die Führer über die Menschen.“",

  // 8: 3eaa8624-b73f-452c-9bd4-2ee830e2eb5c
  "Farwah ibn Abi l-Maghra’ berichtete mir: ‘Ali ibn Mushir teilte uns mit, von Hischam, von seinem Vater, von ‘A’ischah (möge Allah mit ihr zufrieden sein), die sagte: Eine schwarze Sklavin, die einigen Arabern gehörte, nahm den Islam an; sie hatte eine kleine Hütte in der Moschee. Sie pflegte zu uns zu kommen und sich mit uns zu unterhalten. Wann immer sie ihre Rede beendete, sprach sie: „Und der Tag des Ledergürtels gehört zu den Wundern unseres Herrn; fürwahr, Er hat mich aus dem Lande des Unglaubens errettet!“ Als sie dies wiederholt sagte, fragte ‘A’ischah sie: „Was hat es mit dem Tag des Gürtels auf sich?“ Sie sagte: „Ein junges Mädchen aus der Familie meiner Herren ging mit einem roten Ledergürtel hinaus, der mit Perlen verziert war. Er fiel von ihr herab, und ein Milan stieß herab, hielt ihn für Fleisch und schnappte ihn sich. Da beschuldigten sie mich, ihn gestohlen zu haben, und quälten mich, bis sie sogar meine Schamteile durchsuchten! Während sie um mich herumstanden und ich in tiefster Bedrängnis war, flog der Milan heran, bis er genau über unseren Köpfen schwebte, und ließ den Gürtel fallen! Sie nahmen ihn an sich, und ich sagte zu ihnen: ‚Dies ist es, dessen ihr mich beschuldigt habt, während ich völlig unschuldig daran war!‘“",

  // 9: d10fc487-5598-4739-9f65-60fa841ee5ea
  "Abu Ma‘mar berichtete uns: ‘Abd al-Warith berichtete uns: Qatan Abu l-Haytham berichtete uns: Abu Yazid al-Madani berichtete uns von ‘Ikrimah, von Ibn ‘Abbas (möge Allah mit beiden zufrieden sein), der sagte: Der erste Bluteid (Qasamah) in der Zeit der Gahiliyyah wegen eines Mordes trug sich bei uns, den Banu Haschim, zu. Ein Mann von den Banu Haschim verdingte sich als Lohnknecht bei einem Mann aus einer anderen Sippe der Quraisch. Er zog mit ihm und seinen Kamelen aus. Da kam ein anderer Mann von den Banu Haschim an ihm vorbei, dessen Traggurt am Reitsack gerissen war. Er sagte: „Hilf mir mit einem Seilring aus, damit ich den Riemen meines Reitsacks festbinden kann und die Kamele nicht auseinanderlaufen!“ Der Lohnknecht gab ihm einen Seilring, und jener befestigte damit seinen Sack. Als sie lagerten, band der Mann alle Kamele mit Seilen fest, bis auf ein einziges Kamel. Der Dienstherr fragte: „Was ist mit diesem Kamel los? Warum ist es als einziges unter den Kamelen unangebunden geblieben?“ Er sagte: „Es hat keinen Seilring.“ Da schleuderte der Mann einen Holzstab nach ihm, der seinen Tod herbeiführte. Ein Mann aus dem Jemen kam an dem Sterbenden vorbei, und dieser fragte ihn: „Wirst du die Pilgerzeit besuchen?“ Jener sagte: „Ich besuche sie nicht regelmäßig, doch vielleicht nehme ich daran teil.“ Der Verwundete fragte: „Würdest du eine Botschaft von mir überbringen, wenn du hingehst?“ Jener sagte: „Ja.“ Er sprach: „Wenn du zur Pilgerzeit kommst, so rufe laut: ‚O Sippschaft der Quraisch!‘ Wenn sie dir antworten, rufe: ‚O Sippschaft der Banu Haschim!‘ Wenn sie dir antworten, frage nach Abu Talib und richte ihm aus, dass Soundso mich wegen eines Seilrings erschlagen hat!“ Dann verschied der Lohnknecht. Als der Dienstherr nach Mekka zurückkehrte, trat Abu Talib an ihn heran und fragte: „Was ist mit unserem Gefährten geschehen?“ Er antwortete: „Er erkrankte schwer, und ich pflegte ihn auf das Beste; und ich war es, der ihn begrub.“ Da sagte Abu Talib: „Das ziemt sich für einen Mann wie dich.“ Einige Zeit verging. Dann besuchte jener Mann, dem die Botschaft anvertraut worden war, die Pilgerzeit in Mekka und rief laut: „O Sippschaft der Quraisch!“ Sie sagten: „Hier sind die Quraisch.“ Er rief: „O Sippschaft der Banu Haschim!“ Sie sagten: „Hier sind die Banu Haschim.“ Er fragte: „Wo ist Abu Talib?“ Sie sagten: „Hier ist Abu Talib.“ Da sagte er: „Soundso hat mir aufgetragen, dir eine Botschaft zu überbringen: Dass Soundso ihn wegen eines Seilrings erschlagen hat!“ Da ging Abu Talib zu jenem Mann und sprach: „Wähle eine von drei Möglichkeiten: Entweder zahlst du ein Blutgeld von einhundert Kamelen, da du unseren Gefährten getötet hast; oder fünfzig Männer aus deinem Volk leisten einen Eid, dass du ihn nicht getötet hast; oder wenn du dich weigerst, töten wir dich als Vergeltung für ihn!“ Da ging der Mann zu seinem Volk, und sie sprachen: „Wir werden den Eid leisten.“ Da kam eine Frau von den Banu Haschim, die mit einem Mann aus jenem Stamm verheiratet war und ihm einen Sohn geboren hatte, zu Abu Talib und sprach: „O Abu Talib, ich wünsche, dass du meinen Sohn von den fünfzig Männern ausnimmst und ihn nicht dort schwören lässt, wo die Eide geleistet werden!“ Das gewährte er ihr. Dann kam ein Mann von ihnen zu Abu Talib und sprach: „Du hast verlangt, dass fünfzig Männer anstelle von einhundert Kamelen schwören, was zwei Kamele für jeden Mann ausmacht. Hier sind zwei Kamele, nimm sie von mir an und lass mich nicht dort schwören, wo die Eide geleistet werden!“ Abu Talib nahm die beiden Kamele an. So traten achtundvierzig Männer an und leisteten den falschen Eid. Ibn ‘Abbas sagte: Bei Dem, in Dessen Hand meine Seele liegt: Kein einziges Jahr verging, bis auch nicht ein einziger von jenen achtundvierzig Männern mehr mit dem Auge blinzelte (sie starben allesamt)! Auch kein einziger von ihnen überlebte das Jahr.",

  // 10: c6a054f6-8971-4f0d-addb-699587750410
  "‘Amr ibn ‘Abbas berichtete mir: ‘Abd ar-Rahman ibn Mahdi berichtete uns: al-Muthanna berichtete uns von Abu Jamrah, von Ibn ‘Abbas (möge Allah mit beiden zufrieden sein), der sagte: Als Abu Dharr von der Entsendung des Propheten (Friede sei auf ihm) erfuhr, sagte er zu seinem Bruder: „Reite in dieses Tal und bringe mir Kunde von diesem Mann, der behauptet, ein Prophet zu sein, zu dem Kunde aus dem Himmel kommt; höre dir etwas von seinen Worten an und kehre dann zu mir zurück!“ Da ritt sein Bruder aus, bis er ihn erreichte und einige seiner Worte hörte. Dann kehrte er zu Abu Dharr zurück und sagte: „Ich sah ihn edle Charaktereigenschaften gebieten, und ich hörte Worte, die keineswegs Dichtung sind.“ Abu Dharr sagte: „Du hast meinen Wissensdurst nicht gestillt.“ So schnürte er seinen Proviantbeutel, nahm einen abgenutzten Wasserschlauch voll Wasser und zog aus, bis er Mekka erreichte. Er begab sich zur Moschee und suchte nach dem Propheten (Friede sei auf ihm), doch er kannte ihn nicht und scheute sich, nach ihm zu fragen. Als ein Teil der Nacht vergangen war, erblickte ‘Ali ihn und erkannte, dass er ein Fremder war. Als ‘Ali ihn sah, folgte er ihm, doch keiner von beiden fragte den anderen nach irgendetwas, bis der Morgen anbrach. Dann nahm Abu Dharr seinen Wasserschlauch und seinen Proviant mit zur Moschee und verbrachte dort jenen Tag, ohne dass der Prophet (Friede sei auf ihm) ihn bis zum Abend sah. Da kehrte er zu seiner Schlafstätte zurück. Da kam ‘Ali wieder an ihm vorbei und sprach: „Ist es für den Mann nicht an der Zeit, seine Herberge zu kennen?“ Da ließ er ihn aufstehen und nahm ihn mit sich, doch keiner von beiden fragte den anderen nach irgendetwas, bis der dritte Tag anbrach. Da verfuhr ‘Ali auf dieselbe Weise und beherbergte ihn bei sich. Dann sprach ‘Ali: „Willst du mir nicht mitteilen, was dich hierhergeführt hat?“ Abu Dharr sagte: „Wenn du mir ein festes Versprechen gibst, dass du mich rechtleitest, tue ich es.“ Da tat ‘Ali dies, und Abu Dharr berichtete es ihm. Da sprach ‘Ali: „Wahrlich, es ist die reine Wahrheit; er ist der Gesandte Allahs (Friede sei auf ihm)! Wenn der Morgen anbricht, so folge mir! Wenn ich etwas sehe, worum ich für dich fürchte, werde ich stehen bleiben, als wollte ich meine Notdurft verrichten; wenn ich aber weitergehe, so folge mir, bis du dorthin eintrittst, wo ich eintrete.“ Abu Dharr tat dies und folgte seinen Schritten, bis ‘Ali beim Propheten (Friede sei auf ihm) eintrat und Abu Dharr mit ihm eintrat. Da hörte er seine Worte und nahm sogleich an Ort und Stelle den Islam an. Da sprach der Prophet (Friede sei auf ihm) zu ihm: „Kehre zu deinem Volk zurück und verkünde es ihnen, bis mein Befehl zu dir kommt!“ Abu Dharr sagte: „Bei Dem, in Dessen Hand meine Seele liegt, ich werde dies gewiss lautstark mitten unter ihnen verkünden!“ Da ging er hinaus, bis er die Moschee erreichte, und rief mit erhobener Stimme aus: „Ich bezeuge, dass es keinen Gott gibt außer Allah und dass Muhammad der Gesandte Allahs ist!“ Da sprangen die Götzendiener auf ihn ein und schlugen auf ihn ein, bis sie ihn zu Boden warfen. Da kam al-‘Abbas herbeigeeilt, warf sich schützend über ihn und rief: „Wehe euch! Wisst ihr denn nicht, dass er vom Stamme Ghifar ist und dass eure Handelskarawanen nach Scham (Syrien) an ihrem Gebiet vorbeiziehen müssen?“ So rettete er ihn aus ihren Händen. Am nächsten Tag kehrte Abu Dharr zurück und rief dieselben Worte aus. Da fielen sie erneut über ihn her und schlugen ihn, woraufhin al-‘Abbas sich abermals schützend über ihn warf.",

  // 11: 4f2f1e8b-dc01-4431-af4e-26eead240255
  "Qutaybah ibn Sa‘id berichtete uns: Sufyan berichtete uns von Isma‘il, von Qays, der sagte: Ich hörte Sa‘id ibn Zayd ibn ‘Amr ibn Nufayl in der Moschee von Kufa sagen: „Bei Allah, ich erinnere mich wohl daran, wie ‘Umar mich wegen des Islam in Fesseln schlug, bevor ‘Umar selbst den Islam annahm! Und wenn der Berg Uhud zerspringen würde wegen dessen, was ihr ‘Uthman angetan habt, so hätte er vollauf das Recht, zu zerspringen!“",

  // 12: f5d23af3-598b-4165-a63f-74d709751577
  "Yahya ibn Sulayman berichtete uns: Ibn Wahb sagte: ‘Umar ibn Muhammad berichtete mir: Mein Großvater Zayd ibn ‘Abdullah ibn ‘Umar teilte mir von seinem Vater mit, der sagte: Während ‘Umar voller Furcht in seinem Hause saß, trat plötzlich al-‘As ibn Wa’il as-Sahmi, Abu ‘Amr, bei ihm ein, bekleidet mit einem gestreiften jemenitischen Obergewand und einem mit Seide eingefassten Hemd; und er gehörte zu den Banu Sahm, die in der Gahiliyyah unsere Verbündeten waren. Er sprach zu ihm: „Was ist mit dir?“ ‘Umar antwortete: „Dein Volk behauptet, dass sie mich töten wollen, wenn ich den Islam annehme.“ Da sprach al-‘As: „Sie haben keinen Weg gegen dich!“ Nachdem er dies gesagt hatte, fühlte ich mich sicher. Da ging al-‘As hinaus und traf die Menschen, die das ganze Tal füllten. Er fragte: „Wohin wollt ihr?“ Sie sagten: „Wir wollen zu diesem Sohn von al-Khattab, der seine Religion verlassen hat!“ Da sprach er: „Es gibt keinen Weg gegen ihn!“ Da wandten sich die Menschen um und kehrten um.",

  // 13: 17b1486e-a45b-4ece-adb9-774f648a7d35 (Himmelfahrt / al-Mi‘raj)
  "Hudbah ibn Khalid berichtete uns: Hammam ibn Yahya berichtete uns: Qatadah berichtete uns von Anas ibn Malik, von Malik ibn Sa‘sa‘ah (möge Allah mit beiden zufrieden sein), dass der Prophet Allahs (Friede sei auf ihm) ihnen von der Nacht berichtete, in der er auf die Nachtreise entführt wurde; er sagte: „Während ich im Hatim – oder vielleicht sagte er: im Hidschr – an der Kaaba lag, kam plötzlich jemand zu mir und spaltete mich auf.“ Er sagte: Und ich hörte ihn sagen: „Er spaltete auf, was zwischen hier und hier lag.“ Ich fragte al-Jarud, der neben mir saß: „Was meint er damit?“ Er sagte: „Von der Grube seiner Kehle bis zu seinem Schamhaar“ – oder er hörte ihn sagen: „von seiner Brust bis zu seinem Schamhaar“. Er sagte: „Dann nahm er mein Herz heraus. Daraufhin wurde eine goldene Schale herbeigebracht, die voll von Glauben (Iman) war. Mein Herz wurde gewaschen und dann wieder damit angefüllt. Danach wurde mir ein weißes Reittier gebracht, kleiner als ein Maultier und größer als ein Esel.“ Da sagte al-Jarud zu ihm: „Dies war al-Buraq, o Abu Hamzah?“ Anas sagte: „Ja. Es setzte seinen Huf dorthin, wohin sein Blick reichte.“ Er sagte: „Ich wurde darauf getragen, und Gabriel zog mit mir aus, bis er den untersten Himmel erreichte. Er bat um Einlass, woraufhin gefragt wurde: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Da wurde geöffnet. Als ich eintrat, erblickte ich Adam. Gabriel sagte: ‚Dies ist dein Vater Adam, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Sohn und der rechtschaffene Prophet!‘ Dann stieg Gabriel mit mir empor, bis er zum zweiten Himmel kam, und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Da wurde geöffnet. Als ich eintrat, erblickte ich Yahya (Johannes) und ‘Isa (Jesus), die beiden Söhne zweier Tanten mütterlicherseits. Gabriel sagte: ‚Dies sind Yahya und ‘Isa, so grüße sie!‘ Ich grüßte sie, und sie erwiderten den Gruß. Dann sprachen sie: ‚Willkommen sei der rechtschaffene Bruder und der rechtschaffene Prophet!‘ Dann stieg er mit mir zum dritten Himmel empor und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Da wurde geöffnet. Als ich eintrat, erblickte ich Joseph (Yusuf). Gabriel sagte: ‚Dies ist Joseph, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Bruder und der rechtschaffene Prophet!‘ Dann stieg er mit mir empor, bis er zum vierten Himmel kam, und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Da wurde geöffnet. Als ich eintrat, erblickte ich Idris (Henoch). Gabriel sagte: ‚Dies ist Idris, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Bruder und der rechtschaffene Prophet!‘ Dann stieg er mit mir empor, bis er zum fünften Himmel kam, und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad (Friede sei auf ihm).‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Als ich eintrat, erblickte ich Aaron (Harun). Gabriel sagte: ‚Dies ist Aaron, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Bruder und der rechtschaffene Prophet!‘ Dann stieg er mit mir empor, bis er zum sechsten Himmel kam, und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Als ich eintrat, erblickte ich Moses (Musa). Gabriel sagte: ‚Dies ist Moses, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Bruder und der rechtschaffene Prophet!‘ Als ich an ihm vorbeiging, weinte er. Man fragte ihn: ‚Was bringt dich zum Weinen?‘ Er sprach: ‚Ich weine, weil nach mir ein junger Mann entsandt wurde, von dessen Gemeinschaft mehr Menschen ins Paradies eintreten werden als von meiner Gemeinschaft!‘ Dann stieg Gabriel mit mir zum siebten Himmel empor und bat um Einlass. Man fragte: ‚Wer ist da?‘ Er sagte: ‚Gabriel.‘ Man fragte: ‚Und wer ist mit dir?‘ Er sagte: ‚Muhammad.‘ Man fragte: ‚Wurde er denn entsandt?‘ Er sagte: ‚Ja.‘ Da hieß es: ‚Seid willkommen! Welch trefflicher Ankömmling ist er!‘ Als ich eintrat, erblickte ich Abraham (Ibrahim). Gabriel sagte: ‚Dies ist dein Vater Abraham, so grüße ihn!‘ Ich grüßte ihn, und er erwiderte den Gruß. Dann sprach er: ‚Willkommen sei der rechtschaffene Sohn und der rechtschaffene Prophet!‘ Dann wurde mir der Lotusbaum des äußersten Endes (Sidrat al-Muntaha) emporgehoben: Seine Früchte waren wie die Tonkrüge von Hajar und seine Blätter wie die Ohren von Elefanten! Gabriel sprach: ‚Dies ist Sidrat al-Muntaha.‘ Und da waren vier Flüsse: zwei verborgene Flüsse und zwei sichtbare Flüsse. Ich fragte: ‚Was sind diese beiden, o Gabriel?‘ Er sprach: ‚Was die beiden verborgenen anbelangt, so sind es zwei Flüsse im Paradiese; was aber die beiden sichtbaren anbelangt, so sind es der Nil und der Euphrat.‘ Dann wurde mir das vielbesuchte Gotteshaus (al-Bayt al-Ma‘mur) emporgehoben. Dann wurden mir ein Gefäß mit Wein, ein Gefäß mit Milch und ein Gefäß mit Honig gereicht. Da wählte ich die Milch. Gabriel sprach: ‚Dies ist die natürliche Veranlagung (Fitrah), auf der du und deine Gemeinschaft seid!‘ Dann wurden mir fünfzig Gebete für jeden Tag zur Pflicht auferlegt. Ich kehrte zurück und kam an Moses vorbei. Er fragte: ‚Was wurde dir aufgetragen?‘ Ich sprach: ‚Mir wurden fünfzig Gebete für jeden Tag aufgetragen.‘ Moses sprach: ‚Deine Gemeinschaft wird nicht imstande sein, täglich fünfzig Gebete zu verrichten! Bei Allah, ich habe die Menschen vor dir erprobt und mich mit den Kindern Israels auf das Härteste abgemüht! Kehre zurück zu deinem Herrn und bitte Ihn um Erleichterung für deine Gemeinschaft!‘ Da kehrte ich um, und Er erließ mir zehn davon. Da kehrte ich zu Moses zurück, und er sprach dasselbe zu mir. Ich kehrte abermals um, und Er erließ mir weitere zehn. Ich kehrte zu Moses zurück, und er sprach dasselbe zu mir. Ich kehrte abermals um, und Er erließ mir weitere zehn. Ich kehrte zu Moses zurück, und er sprach dasselbe zu mir. Da kehrte ich um, und mir wurden zehn Gebete für jeden Tag aufgetragen. Ich kehrte zu Moses zurück, und er sprach dasselbe zu mir. Da kehrte ich um, und mir wurden fünf Gebete für jeden Tag aufgetragen. Da ging ich zu Moses zurück. Er fragte: ‚Was wurde dir aufgetragen?‘ Ich sprach: ‚Mir wurden fünf Gebete für jeden Tag aufgetragen.‘ Moses sprach: ‚Deine Gemeinschaft wird nicht imstande sein, täglich fünf Gebete zu verrichten! Ich habe die Menschen vor dir erprobt und mich mit den Kindern Israels auf das Härteste abgemüht! Kehre zu deinem Herrn zurück und bitte Ihn um Erleichterung für deine Gemeinschaft!‘ Da sprach ich: ‚Ich habe meinen Herrn gebeten, bis ich mich vor Ihm schäme; doch ich gebe mich zufrieden und füge mich!‘ Als ich weiterging, rief ein Rufer aus: ‚Ich habe Meine Pflichtverordnung bestätigt und Meinen Dienern Erleichterung gewährt!‘“",

  // 14: ce13e940-2fa5-4fd2-a76e-e3185b67de6d
  "Yahya ibn Bukayr berichtete uns: al-Layth berichtete uns von ‘Uqayl, von Ibn Schihab. Und Ahmad ibn Salih berichtete uns: ‘Anbasah berichtete uns: Yunus berichtete uns von Ibn Schihab, der sagte: ‘Abd ar-Rahman ibn ‘Abdullah ibn Ka‘b ibn Malik teilte mir mit, dass ‘Abdullah ibn Ka‘b – der Ka‘b zu führen pflegte, als dieser erblindet war – sagte: Ich hörte Ka‘b ibn Malik die Begebenheit in voller Länge erzählen, als er beim Feldzug nach Tabuk hinter dem Propheten (Friede sei auf ihm) zurückgeblieben war. Ibn Bukayr fügte in seiner Überlieferung hinzu: „Und fürwahr, ich war mit dem Propheten (Friede sei auf ihm) in der Nacht von al-‘Aqabah anwesend, als wir den festen Bund auf den Islam schlossen; und ich möchte jene Nacht nicht einmal gegen die Teilnahme an Badr eintauschen, wenngleich Badr unter den Menschen noch berühmter ist als jene.“"
];

if (inputs.length !== translations.length) {
  console.error(`Count mismatch: ${inputs.length} inputs vs ${translations.length} translations`);
  process.exit(1);
}

const outputs = [];
let hasErrors = false;

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const deText = translations[i];
  const errs = validateGerman(item, deText);

  if (errs.length > 0) {
    console.error(`[Error] Item ${i} (${item.id}):`, errs);
    hasErrors = true;
  }

  outputs.push({
    id: item.id,
    de: deText
  });
}

if (hasErrors) {
  console.error('Validation failed. Aborting output writing.');
  process.exit(1);
}

fs.writeFileSync(outputPath, JSON.stringify(outputs, null, 2), 'utf8');
console.log(`Successfully generated and validated ${outputs.length} translations -> ${outputPath}`);
